CREATE TABLE IF NOT EXISTS gis_identity_evidence_resolutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_id uuid NOT NULL REFERENCES gis_identity_exception_resolutions(id) ON DELETE CASCADE, decision text NOT NULL, confidence text NOT NULL, auto_resolved boolean NOT NULL DEFAULT false, rationale text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(exception_id));